import { WzPropertyType } from "../WzPropertyType.js";
import { WzExtended } from "../WzExtended.js";
import { WzImageProperty } from "../WzImageProperty.js";
import { WzImage } from "../WzImage.js";
import { WzDirectory } from "../WzDirectory.js";
import { ErrorLevel, ErrorLogger } from "../util/ErrorLogger.js";
/**
 * @public
 */
export class WzUOLProperty extends WzExtended {
    constructor(name = '', val = '') {
        super();
        this.name = name;
        this.val = val;
        this.linkVal = null;
        this.parent = null;
    }
    get propertyType() {
        return WzPropertyType.UOL;
    }
    dispose() {
        if (this._disposed)
            return;
        this._disposed = true;
    }
    get value() {
        return this.val;
    }
    get wzValue() {
        if (WzUOLProperty.UOLRES) {
            return this.linkValue;
        }
        return this;
    }
    get wzProperties() {
        return this.linkValue instanceof WzImageProperty ? this.linkValue.wzProperties : null;
    }
    at(name) {
        return this.linkValue instanceof WzImageProperty ? this.linkValue.at(name) : this.linkValue instanceof WzImage ? this.linkValue.at(name) : null;
    }
    getFromPath(path) {
        return this.linkValue instanceof WzImageProperty ? this.linkValue.getFromPath(path) : this.linkValue instanceof WzImage ? this.linkValue.getFromPath(path) : null;
    }
    get linkValue() {
        if (this.linkVal == null) {
            const paths = this.val.split(/[\\/]/);
            this.linkVal = this.parent;
            // @ts-expect-error ignore
            // eslint-disable-next-line @typescript-eslint/no-unused-vars
            const asdf = this.parent.fullPath;
            for (const path of paths) {
                if (path === '..') {
                    this.linkVal = this.linkVal.parent;
                }
                else {
                    if (this.linkVal instanceof WzImageProperty) {
                        this.linkVal = this.linkVal.at(path);
                    }
                    else if (this.linkVal instanceof WzImage) {
                        this.linkVal = this.linkVal.at(path);
                    }
                    else if (this.linkVal instanceof WzDirectory) {
                        if (path.endsWith('.img')) {
                            this.linkVal = this.linkVal.at(path);
                        }
                        else {
                            this.linkVal = this.linkVal.at(path + '.img');
                        }
                    }
                    else {
                        ErrorLogger.log(ErrorLevel.Critical, `UOL got nexon'd at property: ${this.fullPath}`);
                        return null;
                    }
                }
            }
        }
        return this.linkVal;
    }
    setValue(value) {
        this.val = value;
    }
    toString() {
        return this.val;
    }
    async getBitmap() {
        if (this.linkValue != null) {
            return await this.linkValue.getBitmap();
        }
        return null;
    }
}
WzUOLProperty.UOLRES = true;
